    17	    private static final String COLUMNS = """
    18	            id, customer_cpf, status, created_at, tracking_code, payment_transaction_id, payment_outcome,
    19	            products_subtotal, coupon_discount, shipping_cost, delivery_days, insurance, payment_adjustment,
    20	            final_total, installments, installment_amount, next_purchase_credit, gift""";
