    28	    public void insert(Order o) {
    29	        OrderSummary s = o.summary();
    30	        jdbc.sql("""
    31	                INSERT INTO orders (id, customer_cpf, status, created_at, products_subtotal, coupon_discount,
    32	                    shipping_cost, delivery_days, insurance, payment_adjustment, final_total, installments,
    33	                    installment_amount, next_purchase_credit, gift)
    34	                VALUES (:id, :cpf, :status, :createdAt, :subtotal, :discount, :shipping, :days, :insurance,
    35	                    :adjustment, :total, :installments, :installment, :credit, :gift)""")
    36	                .param("id", o.id()).param("cpf", o.customerCpf()).param("status", o.status().name())
    37	                .param("createdAt", OffsetDateTime.ofInstant(o.createdAt(), ZoneOffset.UTC))
    38	                .param("subtotal", s.productsSubtotal()).param("discount", s.couponDiscount())
    39	                .param("shipping", s.shippingCost()).param("days", s.deliveryDays())
    40	                .param("insurance", s.insurance()).param("adjustment", s.paymentAdjustment())
    41	                .param("total", s.finalTotal()).param("installments", s.installments())
    42	                .param("installment", s.installmentAmount()).param("credit", s.nextPurchaseCredit())
    43	                .param("gift", s.gift()).update();
    44	        int line = 0;
    45	        for (OrderItem item : o.items()) {
    46	            jdbc.sql("INSERT INTO order_items (order_id, line_no, sku, quantity) VALUES (:id, :line, :sku, :q)")
    47	                    .param("id", o.id()).param("line", line++).param("sku", item.sku())
    48	                    .param("q", item.quantity()).update();
    49	        }
    50	    }
