    61	    private Optional<Order> find(String sql, String id) {
    62	        return jdbc.sql(sql).param("id", id).query((rs, n) -> {
    63	            List<OrderItem> items = jdbc
    64	                    .sql("SELECT sku, quantity FROM order_items WHERE order_id = :id ORDER BY line_no")
    65	                    .param("id", id).query((r, i) -> new OrderItem(r.getString("sku"), r.getInt("quantity")))
    66	                    .list();
    67	            OrderSummary summary = new OrderSummary(money(rs, "products_subtotal"), money(rs, "coupon_discount"),
    68	                    money(rs, "shipping_cost"), rs.getInt("delivery_days"), money(rs, "insurance"),
    69	                    money(rs, "payment_adjustment"), money(rs, "final_total"), rs.getInt("installments"),
    70	                    money(rs, "installment_amount"), money(rs, "next_purchase_credit"), rs.getBoolean("gift"));
    71	            Instant createdAt = rs.getObject("created_at", OffsetDateTime.class).toInstant();
    72	            return new Order(rs.getString("id"), rs.getString("customer_cpf"),
    73	                    OrderStatus.valueOf(rs.getString("status")), createdAt, summary, items,
    74	                    rs.getString("tracking_code"), rs.getString("payment_transaction_id"),
    75	                    rs.getString("payment_outcome"));
    76	        }).optional();
