81	    31	/** Calcula o resumo da compra. É a única fonte dos valores, tanto do resumo quanto do pedido registrado. */
82	    32	@Service
83	    33	public class CheckoutService {
84	    34	
85	    35	    private static final String COUPON_CAP_RATE = "0.30";
86	    36	
87	    37	    private final ProductRepository products;
88	    38	    private final OrderRepository orders;
89	    39	    private final Map<String, ShippingOption> shippingOptions;
90	    40	    private final Map<String, Coupon> coupons;
91	    41	    private final Map<String, ClubTier> tiers;
92	    42	    private final Map<String, PaymentOption> paymentOptions;
93	    43	
94	    44	    CheckoutService(ProductRepository products, OrderRepository orders, List<ShippingOption> shippingOptions,
95	    45	                    List<Coupon> coupons, List<ClubTier> tiers, List<PaymentOption> paymentOptions) {
96	    46	        this.products = products;
97	    47	        this.orders = orders;
98	    48	        this.shippingOptions = index(shippingOptions, ShippingOption::code);
99	    49	        this.coupons = index(coupons, Coupon::code);
100	    50	        this.tiers = index(tiers, ClubTier::code);
101	    51	        this.paymentOptions = index(paymentOptions, PaymentOption::code);
102	    52	    }
103	    53	
104	    54	    public OrderSummary summarize(CheckoutRequest request) {
105	    55	        validateStructure(request);
106	    56	        List<CartLine> lines = loadLines(request.items());
107	    57	
108	    58	        ClubTier tier = find(tiers, request.clubTier(), ErrorCode.INVALID_CLUB_TIER);
109	    59	        Region region = Region.parse(request.region()).orElseThrow(() -> new ApiException(ErrorCode.INVALID_REGION));
110	    60	        String zip = request.zipCode();
111	    61	        if (zip == null || !zip.matches("\\d{8}")) {
112	    62	            throw new ApiException(ErrorCode.INVALID_ZIP_CODE);
113	    63	        }
114	    64	        ShippingOption shipping = find(shippingOptions, request.shippingMethod(), ErrorCode.INVALID_SHIPPING_METHOD);
115	    65	
116	    66	        BigDecimal subtotal = lines.stream().map(CartLine::total).reduce(Money.ZERO, BigDecimal::add);
117	    67	        BigDecimal weight = lines.stream()
118	    68	                .map(l -> l.product().weightKg().multiply(BigDecimal.valueOf(l.quantity())))
119	    69	                .reduce(BigDecimal.ZERO, BigDecimal::add);
120	    70	        ShippingQuote quote = shipping.quote(new ShippingRequest(zip, region, weight));
121	    71	        BigDecimal shippingCost = tier.waivesFreight() && shipping.freightWaivableByClub() ? Money.ZERO
122	    72	                : quote.cost();
123	    73	
124	    74	        BigDecimal couponDiscount = Money.ZERO;
125	    75	        if (request.coupon() != null) {
126	    76	            Coupon coupon = find(coupons, request.coupon(), ErrorCode.INVALID_COUPON);
127	    77	            boolean firstPurchase = !orders.hasPurchaseByCustomer(request.customer().cpf());
128	    78	            BigDecimal raw = coupon.discount(new CouponContext(lines, subtotal, shipping, shippingCost, firstPurchase));
129	    79	            couponDiscount = Money.round(raw).min(Money.percent(subtotal, COUPON_CAP_RATE));
130	    80	        }
131	    81	
132	    82	        PaymentOption payment = find(paymentOptions, request.paymentMethod(), ErrorCode.INVALID_PAYMENT_METHOD);
133	    83	        int installments = request.installments() == null ? 1 : request.installments();
134	    84	        payment.validateInstallments(installments);
135	    85	
136	    86	        BigDecimal insurance = region.insuranceFor(subtotal);
137	    87	        BigDecimal orderTotal = subtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
138	    88	        payment.validateAvailability(orderTotal);
139	    89	        PaymentCharge charge = payment.charge(new PaymentContext(orderTotal, installments, request.coupon() != null));
140	    90	
141	    91	        return new OrderSummary(subtotal, couponDiscount, shippingCost, quote.days(), insurance,
142	    92	                charge.finalTotal().subtract(orderTotal), charge.finalTotal(), installments,
143	    93	                charge.installmentAmount(), tier.credit(subtotal), tier.gift(subtotal));
144	    94	    }
