146	    96	    private void validateStructure(CheckoutRequest request) {
147	    97	        if (request == null || request.items() == null || request.items().isEmpty()
148	    98	                || request.customer() == null || isBlank(request.customer().cpf())
149	    99	                || isBlank(request.customer().email())) {
150	   100	            throw new ApiException(ErrorCode.INVALID_ORDER);
151	   101	        }
152	   102	        Set<String> seen = new HashSet<>();
153	   103	        for (CheckoutRequest.Item item : request.items()) {
154	   104	            if (item == null || isBlank(item.sku()) || item.quantity() == null || item.quantity() <= 0
155	   105	                    || !seen.add(item.sku())) {
156	   106	                throw new ApiException(ErrorCode.INVALID_ORDER);
157	   107	            }
158	   108	        }
159	   109	    }
