161	   111	    private List<CartLine> loadLines(List<CheckoutRequest.Item> items) {
162	   112	        Map<String, Product> found = products.findAllBySkus(items.stream().map(CheckoutRequest.Item::sku).toList())
163	   113	                .stream().collect(Collectors.toMap(Product::sku, Function.identity()));
164	   114	        if (items.stream().anyMatch(i -> !found.containsKey(i.sku()))) {
165	   115	            throw new ApiException(ErrorCode.UNKNOWN_PRODUCT);
166	   116	        }
167	   117	        if (found.values().stream().anyMatch(Product::discontinued)) {
168	   118	            throw new ApiException(ErrorCode.PRODUCT_DISCONTINUED);
169	   119	        }
170	   120	        if (items.stream().anyMatch(i -> found.get(i.sku()).stock() < i.quantity())) {
171	   121	            throw new ApiException(ErrorCode.INSUFFICIENT_STOCK);
172	   122	        }
173	   123	        return items.stream().map(i -> new CartLine(found.get(i.sku()), i.quantity())).toList();
174	   124	    }
