180	   130	    private static <T> T find(Map<String, T> registry, String code, ErrorCode error) {
181	   131	        T found = code == null ? null : registry.get(code);
182	   132	        if (found == null) {
183	   133	            throw new ApiException(error);
184	   134	        }
185	   135	        return found;
186	   136	    }
