    94	@Component
    95	class CreditCardPayment implements PaymentOption {
    96	
    97	    private static final int MAX_INSTALLMENTS = 12;
    98	    private static final int MAX_INTEREST_FREE = 3;
    99	    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
   100	    private static final MathContext PRECISION = new MathContext(34, RoundingMode.HALF_EVEN);
   101	
   102	    @Override
   103	    public String code() {
   104	        return "CREDIT_CARD";
   105	    }
   106	
   107	    @Override
   108	    public void validateInstallments(int installments) {
   109	        if (installments < 1 || installments > MAX_INSTALLMENTS) {
   110	            throw new ApiException(ErrorCode.INVALID_INSTALLMENTS);
   111	        }
   112	    }
   113	
   114	    @Override
   115	    public PaymentCharge charge(PaymentContext context) {
   116	        BigDecimal total = context.orderTotal();
   117	        int n = context.installments();
   118	        if (n <= MAX_INTEREST_FREE) {
   119	            return new PaymentCharge(total, Money.round(total.divide(BigDecimal.valueOf(n), PRECISION)));
   120	        }
   121	        // Tabela Price: parcela = total * i / (1 - (1 + i)^-n)
   122	        BigDecimal growth = BigDecimal.ONE.add(MONTHLY_RATE).pow(n, PRECISION);
   123	        BigDecimal installment = Money.round(total.multiply(MONTHLY_RATE).multiply(growth)
   124	                .divide(growth.subtract(BigDecimal.ONE), PRECISION));
   125	        return new PaymentCharge(installment.multiply(BigDecimal.valueOf(n)), installment);
   126	    }
   127	}
